import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import path from 'path';

export default defineConfig({
  plugins: [react()],
  root: '.',
  publicDir: 'assets',
  server: {
    host: '0.0.0.0',
    port: 5000,
    allowedHosts: true,
    proxy: {
      '/api': {
        target: 'http://localhost:3001',
        changeOrigin: true,
      },
    },
  },
  build: {
    outDir: 'dist',
  },
  resolve: {
    alias: {
      '@': path.resolve(process.cwd(), 'src/renderer'),
    },
  },
});

arguments.code:
await requestEnvVar({
    requestType: "secret",
    keys: ["VITE_SUPABASE_URL", "VITE_SUPABASE_ANON_KEY"],
    userMessage: "This app connects to a Supabase database. Please provide your Supabase project URL and anonymous key. You can find these in your Supabase project under Settings → API."
});

await configureWorkflow({
    name: "Start application",
    command: "npm run client",
    waitForPort: 5000,
    outputType: "webview"
});

const status = await getWorkflowStatus({ name: "Start application" });
console.log(`State: ${status.state}`);
console.log(`Ports: ${JSON.stringify(status.openPorts)}`);
console.log(`Output:\n${status.output}`);

