    27→  document.body.appendChild(iframe);
    28→  const doc = iframe.contentDocument || (iframe.contentWindow as any)?.document;
    29→  if (!doc) { document.body.removeChild(iframe); return; }
    30→  doc.open(); doc.write(html); doc.close();
    31→  setTimeout(() => {
    32→    try { iframe.contentWindow?.print(); } finally { setTimeout(() => document.body.removeChild(iframe), 1000); }
    33→  }, 300);
    34→}
