import React, { useState, useEffect } from 'react';
import { Save, Upload, Image, AlertCircle, X, Plus, Trash2, GraduationCap } from 'lucide-react';
import { settingsAPI } from '../../lib/api';

interface Settings {
  school_name: string;
  tagline: string;
  phone_number: string;
  logo_url: string | null;
  academic_session: string;
  address: string;
  min_partial_payment_floor: number;
  min_acceptance_partial_floor: number;
  current_term: string;
  class_list: string;
}

const TERMS = ['1st Term', '2nd Term', '3rd Term'];

const DEFAULT_CLASSES = ['JSS1A', 'JSS1B', 'JSS2A', 'JSS2B', 'JSS3A', 'JSS3B', 'SS1A', 'SS1B', 'SS2A', 'SS2B', 'SS3A', 'SS3B'];

const SchoolSettings: React.FC = () => {
  const [settings, setSettings] = useState<Settings>({
    school_name: '', tagline: '', phone_number: '', logo_url: null, academic_session: '',
    address: '', min_partial_payment_floor: 30000, min_acceptance_partial_floor: 5000,
    current_term: '1st Term', class_list: JSON.stringify(DEFAULT_CLASSES),
  });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [logoPreview, setLogoPreview] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState('');

  const [classList, setClassList] = useState<string[]>(DEFAULT_CLASSES);
  const [newClassName, setNewClassName] = useState('');
  const [newArmName, setNewArmName] = useState('');
  const [selectedBase, setSelectedBase] = useState('');

  useEffect(() => {
    settingsAPI.get().then((data) => {
      if (data) {
        setSettings({ ...data, current_term: data.current_term || '1st Term', class_list: data.class_list || JSON.stringify(DEFAULT_CLASSES) });
        setLogoPreview(data.logo_url || null);
        try {
          const parsed = JSON.parse(data.class_list || JSON.stringify(DEFAULT_CLASSES));
          setClassList(Array.isArray(parsed) ? parsed : DEFAULT_CLASSES);
        } catch {
          setClassList(DEFAULT_CLASSES);
        }
      }
    }).catch(console.error).finally(() => setLoading(false));
  }, []);

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) { setErrorMsg('Please select an image file.'); return; }
    if (file.size > 200 * 1024) { setErrorMsg('Image must be under 200KB for receipt printing.'); return; }
    const reader = new FileReader();
    reader.onload = (ev) => {
      const dataUrl = ev.target?.result as string;
      setLogoPreview(dataUrl);
      setSettings((prev) => ({ ...prev, logo_url: dataUrl }));
    };
    reader.readAsDataURL(file);
  };

  const addClass = () => {
    const name = newClassName.trim().toUpperCase();
    if (!name) return;
    if (classList.includes(name)) { setErrorMsg('Class already exists.'); return; }
    const updated = [...classList, name].sort();
    setClassList(updated);
    setNewClassName('');
  };

  const addArm = () => {
    if (!selectedBase || !newArmName.trim()) return;
    const armName = (selectedBase + newArmName.trim()).toUpperCase();
    if (classList.includes(armName)) { setErrorMsg('Arm already exists.'); return; }
    const updated = [...classList, armName].sort();
    setClassList(updated);
    setNewArmName('');
  };

  const removeClass = (cls: string) => {
    setClassList((prev) => prev.filter((c) => c !== cls));
  };

  const baseClasses = [...new Set(classList.map((c) => c.replace(/[A-Z]$/, '')))].filter(Boolean);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    setErrorMsg('');
    try {
      const classListStr = JSON.stringify(classList);
      await settingsAPI.save({ ...settings, class_list: classListStr });
      setSettings((prev) => ({ ...prev, class_list: classListStr }));
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch (err) {
      setErrorMsg('Failed to save: ' + (err as Error).message);
    }
    setSaving(false);
  };

  const field = (label: string, key: keyof Settings, placeholder: string, hint?: string) => (
    <div>
      <label className="block text-sm font-medium text-gray-700 mb-1">{label}</label>
      {hint && <p className="text-xs text-gray-400 mb-1">{hint}</p>}
      <input
        type="text"
        value={(settings[key] as string) || ''}
        onChange={(e) => setSettings((prev) => ({ ...prev, [key]: e.target.value }))}
        placeholder={placeholder}
        className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400"
      />
    </div>
  );

  if (loading) return <div className="flex items-center justify-center h-48"><div className="w-8 h-8 border-4 border-primary-200 border-t-primary-600 rounded-full animate-spin" /></div>;

  return (
    <div className="max-w-2xl space-y-6">
      {errorMsg && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full mx-4 p-6 text-center">
            <div className="w-14 h-14 bg-danger-100 rounded-full flex items-center justify-center mx-auto mb-4"><AlertCircle className="w-7 h-7 text-danger-600" /></div>
            <h2 className="text-lg font-bold mb-2">Error</h2>
            <p className="text-gray-600 text-sm mb-5">{errorMsg}</p>
            <button onClick={() => setErrorMsg('')} className="w-full py-2.5 bg-gray-100 rounded-xl text-gray-700 hover:bg-gray-200 font-medium">OK</button>
          </div>
        </div>
      )}

      {/* Receipt Preview */}
      <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
        <div className="px-6 py-4 border-b">
          <h2 className="font-bold text-gray-900">Receipt Preview</h2>
          <p className="text-xs text-gray-400 mt-0.5">This is how your receipt header will appear when printed</p>
        </div>
        <div className="p-6">
          <div className="w-64 mx-auto bg-white border border-gray-200 rounded-lg p-4 font-mono text-xs text-center shadow-sm">
            {logoPreview ? (
              <img src={logoPreview} alt="School Logo" className="w-16 h-16 object-contain mx-auto mb-2" />
            ) : (
              <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-2"><Image className="w-8 h-8 text-gray-300" /></div>
            )}
            <div className="font-bold text-sm">{settings.school_name || 'School Name'}</div>
            <div className="text-gray-500 text-xs mt-0.5">{settings.tagline || 'School Motto'}</div>
            <div className="border-t border-dashed border-gray-300 my-2" />
            <div className="text-gray-500">{settings.academic_session || '2025/2026'} · {settings.current_term || '1st Term'}</div>
            <div className="border-t border-dashed border-gray-300 my-2" />
            <div className="text-gray-400">
              <div>Item Name .......... ₦0.00</div>
              <div className="border-t border-gray-300 mt-1 pt-1 font-bold">TOTAL: ₦0.00</div>
            </div>
            <div className="border-t border-dashed border-gray-300 my-2" />
            {settings.address && <div className="text-gray-400">{settings.address}</div>}
            {settings.phone_number && <div className="text-gray-400">Tel: {settings.phone_number}</div>}
          </div>
        </div>
      </div>

      <form onSubmit={handleSave} className="space-y-6">
        {/* School Information */}
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-6 space-y-5">
          <h2 className="font-bold text-gray-900">School Information</h2>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">School Logo</label>
            <p className="text-xs text-gray-400 mb-2">Upload a logo to appear on receipts. Max 200KB, PNG/JPG.</p>
            <div className="flex items-center gap-3">
              {logoPreview ? (
                <img src={logoPreview} alt="Logo" className="w-14 h-14 object-contain rounded-lg border border-gray-200" />
              ) : (
                <div className="w-14 h-14 bg-gray-100 rounded-lg flex items-center justify-center border border-dashed border-gray-300"><Image className="w-6 h-6 text-gray-400" /></div>
              )}
              <div>
                <label className="cursor-pointer inline-flex items-center gap-2 px-3 py-2 bg-gray-100 hover:bg-gray-200 rounded-lg text-sm font-medium text-gray-700 transition-colors">
                  <Upload className="w-4 h-4" /> Upload Logo
                  <input type="file" accept="image/*" onChange={handleLogoChange} className="hidden" />
                </label>
                {logoPreview && (
                  <button type="button" onClick={() => { setLogoPreview(null); setSettings((p) => ({ ...p, logo_url: null })); }} className="ml-2 text-xs text-danger-500 hover:text-danger-700">Remove</button>
                )}
              </div>
            </div>
          </div>

          {field('School Name', 'school_name', "e.g. St. Mary's Secondary School")}
          {field('Motto / Tagline / Slogan', 'tagline', 'e.g. Excellence in Education', 'Displayed on the receipt under the school name')}
          {field('Academic Session', 'academic_session', 'e.g. 2025/2026', 'Used as the default session when creating new fees')}
        </div>

        {/* Term Management */}
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-6">
          <h2 className="font-bold text-gray-900 mb-1">Active Term</h2>
          <p className="text-xs text-gray-400 mb-4">Toggle which term is currently active. This affects fee assignment and filtering.</p>
          <div className="grid grid-cols-3 gap-2">
            {TERMS.map((term) => (
              <button
                key={term}
                type="button"
                onClick={() => setSettings((prev) => ({ ...prev, current_term: term }))}
                className={`py-3 rounded-xl font-semibold border-2 transition-all text-sm ${settings.current_term === term ? 'bg-primary-600 border-primary-600 text-white' : 'bg-white border-gray-200 text-gray-600 hover:border-primary-400'}`}
              >
                {term}
              </button>
            ))}
          </div>
          <p className="text-xs text-primary-600 font-medium mt-3">Currently active: <strong>{settings.current_term || '1st Term'}</strong></p>
        </div>

        {/* Class Management */}
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-6">
          <div className="flex items-center gap-2 mb-1">
            <GraduationCap className="w-5 h-5 text-primary-600" />
            <h2 className="font-bold text-gray-900">Class Management</h2>
          </div>
          <p className="text-xs text-gray-400 mb-5">Define school classes and their arms (e.g. JSS1 with arms JSS1A, JSS1B). These classes are used across the system.</p>

          <div className="grid grid-cols-2 gap-3 mb-4">
            <div>
              <label className="text-xs font-medium text-gray-600 mb-1 block">Add New Class / Arm</label>
              <div className="flex gap-2">
                <input
                  type="text"
                  value={newClassName}
                  onChange={(e) => setNewClassName(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && (e.preventDefault(), addClass())}
                  className="flex-1 px-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400"
                  placeholder="e.g. JSS1A"
                />
                <button type="button" onClick={addClass} className="px-3 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 text-sm font-semibold"><Plus className="w-4 h-4" /></button>
              </div>
            </div>
            <div>
              <label className="text-xs font-medium text-gray-600 mb-1 block">Add Arm to Existing Base</label>
              <div className="flex gap-2">
                <select value={selectedBase} onChange={(e) => setSelectedBase(e.target.value)} className="flex-1 px-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400">
                  <option value="">Base class…</option>
                  {baseClasses.map((b) => <option key={b} value={b}>{b}</option>)}
                </select>
                <input
                  type="text"
                  value={newArmName}
                  onChange={(e) => setNewArmName(e.target.value)}
                  className="w-14 px-2 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400"
                  placeholder="C"
                  maxLength={2}
                />
                <button type="button" onClick={addArm} className="px-3 py-2 bg-success-600 text-white rounded-lg hover:bg-success-700 text-sm font-semibold"><Plus className="w-4 h-4" /></button>
              </div>
            </div>
          </div>

          <div className="flex flex-wrap gap-2">
            {classList.sort().map((cls) => (
              <div key={cls} className="flex items-center gap-1 bg-primary-50 text-primary-800 border border-primary-200 rounded-lg px-3 py-1.5 text-sm font-medium">
                {cls}
                <button type="button" onClick={() => removeClass(cls)} className="ml-1 text-primary-400 hover:text-danger-600 transition-colors"><X className="w-3.5 h-3.5" /></button>
              </div>
            ))}
            {classList.length === 0 && <p className="text-sm text-gray-400 italic">No classes defined. Add classes above.</p>}
          </div>
        </div>

        {/* Partial Payment Floors */}
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-6">
          <h2 className="font-bold text-gray-900 mb-1">Partial Payment Floors</h2>
          <p className="text-xs text-gray-400 mb-4">Minimum amounts allowed for partial payments. Cashier cannot accept less than these amounts.</p>
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Minimum Registration Partial Payment (₦)</label>
              <p className="text-xs text-gray-400 mb-1">Floor for Registration Fee Bundle and School Fees. Default: ₦30,000</p>
              <input type="number" min="0" step="1000" value={(settings.min_partial_payment_floor || 0)} onChange={(e) => setSettings((p) => ({ ...p, min_partial_payment_floor: parseFloat(e.target.value) || 0 }))} className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400" />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Minimum Acceptance Partial Payment (₦)</label>
              <p className="text-xs text-gray-400 mb-1">Floor for Acceptance Fee Bundle. Default: ₦5,000</p>
              <input type="number" min="0" step="1000" value={(settings.min_acceptance_partial_floor || 0)} onChange={(e) => setSettings((p) => ({ ...p, min_acceptance_partial_floor: parseFloat(e.target.value) || 0 }))} className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400" />
            </div>
          </div>
        </div>

        {/* Receipt Footer */}
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-6 space-y-4">
          <h2 className="font-bold text-gray-900">Receipt Footer</h2>
          <p className="text-xs text-gray-400">This information appears at the bottom of every receipt.</p>
          {field('Address', 'address', 'e.g. 12 School Road, Lagos, Nigeria')}
          {field('Phone / Complaint Number', 'phone_number', 'e.g. 08012345678', 'Printed at the bottom of every receipt for queries and complaints')}
        </div>

        <div className="flex items-center justify-between">
          {saved && (
            <div className="flex items-center gap-2 text-success-600 text-sm">
              <AlertCircle className="w-4 h-4" />
              Settings saved successfully!
            </div>
          )}
          <div className="ml-auto">
            <button type="submit" disabled={saving} className="flex items-center gap-2 px-5 py-2.5 bg-primary-600 text-white rounded-lg font-semibold hover:bg-primary-700 disabled:opacity-50">
              <Save className="w-4 h-4" /> {saving ? 'Saving…' : 'Save Settings'}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

export default SchoolSettings;

import React, { useState, useEffect } from 'react';
import { ChevronLeft, ChevronRight, Trash2, Clock, Pencil, AlertTriangle, X, UserPlus } from 'lucide-react';
import { studentAPI, feeTypeAPI, settingsAPI } from '../../lib/api';

const fmt = (n: number) => `₦${(n || 0).toLocaleString('en-NG', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

interface Student { student_id: string; name: string; student_class: string; current_fees_owed: number; admission_type?: 'Returning' | 'New'; }
interface FeeType { id: number; name: string; amount: number; fee_category: string; class_filter: string | null; academic_session: string; }

const DEFAULT_CLASSES = ['JSS1A', 'JSS1B', 'JSS2A', 'JSS2B', 'JSS3A', 'JSS3B', 'SS1A', 'SS1B', 'SS2A', 'SS2B', 'SS3A', 'SS3B'];

const StudentManagement: React.FC = () => {
  const [students, setStudents] = useState<Student[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const pageSize = 15;
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedClass, setSelectedClass] = useState('all');

  const [classes, setClasses] = useState<string[]>(DEFAULT_CLASSES);
  const [feeTypes, setFeeTypes] = useState<FeeType[]>([]);

  const [showModal, setShowModal] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [showEditStudent, setShowEditStudent] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [history, setHistory] = useState<any[]>([]);

  const [formData, setFormData] = useState({ studentId: '', name: '', studentClass: '', selectedFeeIds: [] as number[], admissionType: 'Returning' as 'Returning' | 'New' });
  const [formError, setFormError] = useState('');
  const [formSaving, setFormSaving] = useState(false);

  const [editData, setEditData] = useState({ name: '', studentClass: '', feesOwed: '' });
  const [editSaving, setEditSaving] = useState(false);
  const [editError, setEditError] = useState('');

  const load = () => {
    setLoading(true);
    studentAPI.getAll({ search, class: selectedClass, page, pageSize })
      .then((d) => { setStudents(d.students); setTotal(d.total); })
      .catch(console.error)
      .finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, [search, selectedClass, page]);

  useEffect(() => {
    settingsAPI.get().then((s) => {
      if (s?.class_list) {
        try {
          const parsed = JSON.parse(s.class_list);
          if (Array.isArray(parsed) && parsed.length > 0) setClasses(parsed.sort());
        } catch { /* use default */ }
      }
    }).catch(console.error);
    feeTypeAPI.getAll().then((ft) => setFeeTypes(ft as FeeType[])).catch(console.error);
  }, []);

  const totalPages = Math.ceil(total / pageSize);

  const computeFeesOwed = () => {
    return formData.selectedFeeIds.reduce((sum, id) => {
      const ft = feeTypes.find((f) => f.id === id);
      return sum + (ft ? Number(ft.amount) : 0);
    }, 0);
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name.trim() || !formData.studentClass) { setFormError('Name and class are required.'); return; }
    setFormSaving(true);
    setFormError('');
    const feesOwed = computeFeesOwed();
    const result = await studentAPI.create({
      studentId: formData.studentId || undefined,
      name: formData.name,
      studentClass: formData.studentClass,
      feesOwed,
      admissionType: formData.admissionType,
    });
    if (result.success) {
      for (const feeId of formData.selectedFeeIds) {
        const ft = feeTypes.find((f) => f.id === feeId);
        if (ft) await feeTypeAPI.assignToStudents(feeId, Number(ft.amount), undefined, result.studentId, ft.fee_category as 'standard' | 'registration');
      }
      setShowModal(false);
      setFormData({ studentId: '', name: '', studentClass: '', selectedFeeIds: [], admissionType: 'Returning' });
      load();
    } else setFormError(result.error || 'Failed to create student');
    setFormSaving(false);
  };

  const viewHistory = async (s: Student) => {
    setSelectedStudent(s);
    const h = await studentAPI.getHistory(s.student_id);
    setHistory(h);
    setShowHistory(true);
  };

  const openDeleteConfirm = (s: Student) => { setSelectedStudent(s); setShowDeleteConfirm(true); };
  const handleDelete = async () => {
    if (!selectedStudent) return;
    await studentAPI.delete(selectedStudent.student_id);
    setShowDeleteConfirm(false);
    setSelectedStudent(null);
    load();
  };

  const openEditStudent = (s: Student) => {
    setSelectedStudent(s);
    setEditData({ name: s.name, studentClass: s.student_class, feesOwed: String(s.current_fees_owed) });
    setEditError('');
    setShowEditStudent(true);
  };

  const handleEditStudent = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedStudent) return;
    if (!editData.name.trim() || !editData.studentClass) { setEditError('Name and class are required.'); return; }
    const fees = parseFloat(editData.feesOwed);
    if (isNaN(fees) || fees < 0) { setEditError('Invalid fees amount.'); return; }
    setEditSaving(true);
    setEditError('');
    try {
      await studentAPI.update(selectedStudent.student_id, { name: editData.name.trim(), studentClass: editData.studentClass });
      await studentAPI.updateFees(selectedStudent.student_id, fees);
      setShowEditStudent(false);
      setSelectedStudent(null);
      load();
    } catch (e) { setEditError((e as Error).message); }
    setEditSaving(false);
  };

  const totalFees = students.reduce((sum, s) => sum + s.current_fees_owed, 0);

  const toggleFeeSelection = (id: number) => {
    setFormData((prev) => ({
      ...prev,
      selectedFeeIds: prev.selectedFeeIds.includes(id)
        ? prev.selectedFeeIds.filter((x) => x !== id)
        : [...prev.selectedFeeIds, id],
    }));
  };

  const filteredFeeTypes = feeTypes.filter((ft) =>
    !ft.class_filter || !formData.studentClass || ft.class_filter === formData.studentClass
  );

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl font-bold">Student Management</h1>
          <p className="text-gray-500">{total} students · ₦{totalFees.toLocaleString('en-NG', { minimumFractionDigits: 2 })} shown outstanding</p>
        </div>
        <button
          onClick={() => { setFormData({ studentId: '', name: '', studentClass: '', selectedFeeIds: [], admissionType: 'Returning' }); setFormError(''); setShowModal(true); }}
          className="flex items-center gap-2 px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 font-semibold"
        >
          <UserPlus className="w-4 h-4" /> Add Student
        </button>
      </div>

      <div className="bg-white rounded-lg shadow-sm p-4 mb-6">
        <div className="flex gap-4">
          <input type="text" value={search} onChange={(e) => { setSearch(e.target.value); setPage(1); }} className="flex-1 px-3 py-2 border rounded-md" placeholder="Search by name or ID..." />
          <select value={selectedClass} onChange={(e) => { setSelectedClass(e.target.value); setPage(1); }} className="px-3 py-2 border rounded-md">
            <option value="all">All Classes</option>
            {classes.map((c) => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-sm overflow-hidden">
        <table className="w-full">
          <thead className="bg-gray-50">
            <tr>
              <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase">Student ID</th>
              <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase">Name</th>
              <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase">Class</th>
              <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase">Type</th>
              <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase">Fees Owed</th>
              <th className="text-center px-4 py-3 text-xs font-medium text-gray-500 uppercase">Actions</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr><td colSpan={6} className="text-center py-12 text-gray-400">Loading...</td></tr>
            ) : students.length === 0 ? (
              <tr><td colSpan={6} className="text-center py-12 text-gray-400">No students found</td></tr>
            ) : students.map((s) => (
              <tr key={s.student_id} className="border-t hover:bg-gray-50">
                <td className="px-4 py-3 font-mono text-sm">{s.student_id}</td>
                <td className="px-4 py-3 font-medium">{s.name}</td>
                <td className="px-4 py-3"><span className="px-2 py-1 bg-primary-100 text-primary-800 rounded text-xs">{s.student_class}</span></td>
                <td className="px-4 py-3"><span className={`px-2 py-1 rounded text-xs ${(s.admission_type || 'Returning') === 'Returning' ? 'bg-gray-100 text-gray-700' : 'bg-warning-100 text-warning-700'}`}>{s.admission_type || 'Returning'}</span></td>
                <td className={`px-4 py-3 text-right font-semibold ${s.current_fees_owed > 0 ? 'text-danger-600' : 'text-success-600'}`}>{fmt(s.current_fees_owed)}</td>
                <td className="px-4 py-3 text-center">
                  <button onClick={() => viewHistory(s)} className="px-2 py-1 text-sm bg-gray-100 rounded mr-1 hover:bg-gray-200">History</button>
                  <button onClick={() => openEditStudent(s)} className="px-2 py-1 text-sm bg-primary-100 text-primary-700 rounded mr-1 hover:bg-primary-200 inline-flex items-center gap-1"><Pencil className="w-3 h-3" /> Edit</button>
                  <button onClick={() => openDeleteConfirm(s)} className="px-2 py-1 text-sm bg-danger-100 text-danger-700 rounded hover:bg-danger-200">Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-3 mt-4">
          <button onClick={() => setPage((p) => Math.max(1, p - 1))} disabled={page <= 1} className="p-2 rounded-lg bg-white border hover:bg-gray-50 disabled:opacity-30"><ChevronLeft className="w-4 h-4" /></button>
          <span className="text-sm text-gray-500 font-medium">Page {page} of {totalPages} ({total} students)</span>
          <button onClick={() => setPage((p) => Math.min(totalPages, p + 1))} disabled={page >= totalPages} className="p-2 rounded-lg bg-white border hover:bg-gray-50 disabled:opacity-30"><ChevronRight className="w-4 h-4" /></button>
        </div>
      )}

      {/* Add Student Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full mx-4 p-6 max-h-[90vh] overflow-auto">
            <div className="flex items-center justify-between mb-5">
              <h2 className="text-lg font-bold">Add New Student</h2>
              <button onClick={() => setShowModal(false)} className="text-gray-400 hover:text-gray-600"><X className="w-5 h-5" /></button>
            </div>
            {formError && <div className="bg-danger-50 text-danger-700 text-sm rounded-lg px-4 py-2 mb-4">{formError}</div>}
            <form onSubmit={handleCreate} className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-1">Student ID <span className="text-gray-400 font-normal">(optional)</span></label>
                <input type="text" value={formData.studentId} onChange={(e) => setFormData({ ...formData, studentId: e.target.value })} className="w-full px-3 py-2.5 border rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400" placeholder="Auto-generated as OIS-XXXX if empty" />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Full Name <span className="text-danger-500">*</span></label>
                <input type="text" value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} className="w-full px-3 py-2.5 border rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400" required autoFocus />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Class <span className="text-danger-500">*</span></label>
                <select value={formData.studentClass} onChange={(e) => setFormData({ ...formData, studentClass: e.target.value, selectedFeeIds: [] })} className="w-full px-3 py-2.5 border rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400" required>
                  <option value="">Select Class</option>
                  {classes.map((c) => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Admission Type</label>
                <div className="grid grid-cols-2 gap-2">
                  <button type="button" onClick={() => setFormData({ ...formData, admissionType: 'Returning' })} className={`py-2.5 rounded-lg text-sm font-semibold border-2 transition-all ${formData.admissionType === 'Returning' ? 'bg-primary-600 border-primary-600 text-white' : 'bg-white border-gray-200 text-gray-600 hover:border-primary-400'}`}>Returning</button>
                  <button type="button" onClick={() => setFormData({ ...formData, admissionType: 'New' })} className={`py-2.5 rounded-lg text-sm font-semibold border-2 transition-all ${formData.admissionType === 'New' ? 'bg-warning-500 border-warning-500 text-white' : 'bg-white border-gray-200 text-gray-600 hover:border-warning-400'}`}>New</button>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Initial Fees to Apply</label>
                <p className="text-xs text-gray-400 mb-2">Select fee templates to apply to this student. Leave empty to add no fees.</p>
                {feeTypes.length === 0 ? (
                  <p className="text-xs text-gray-400 italic">No fee types found. Create fee types in Fees Management first.</p>
                ) : filteredFeeTypes.length === 0 ? (
                  <p className="text-xs text-gray-400 italic">No fees available for the selected class.</p>
                ) : (
                  <div className="space-y-2 max-h-40 overflow-auto border border-gray-200 rounded-lg p-2">
                    {filteredFeeTypes.map((ft) => (
                      <label key={ft.id} className={`flex items-center justify-between px-3 py-2 rounded-lg cursor-pointer border transition-all ${formData.selectedFeeIds.includes(ft.id) ? 'border-primary-400 bg-primary-50' : 'border-gray-100 hover:bg-gray-50'}`}>
                        <div className="flex items-center gap-2">
                          <input type="checkbox" checked={formData.selectedFeeIds.includes(ft.id)} onChange={() => toggleFeeSelection(ft.id)} className="rounded" />
                          <div>
                            <div className="text-sm font-medium text-gray-800">{ft.name}</div>
                            {ft.class_filter && <div className="text-xs text-gray-400">{ft.class_filter}</div>}
                          </div>
                        </div>
                        <span className="text-sm font-bold text-gray-700">{fmt(Number(ft.amount))}</span>
                      </label>
                    ))}
                  </div>
                )}
                {formData.selectedFeeIds.length > 0 && (
                  <div className="mt-2 text-sm font-semibold text-primary-700">
                    Total fees to apply: {fmt(computeFeesOwed())}
                  </div>
                )}
              </div>
              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setShowModal(false)} className="flex-1 py-2.5 bg-gray-100 rounded-xl text-sm font-medium hover:bg-gray-200">Cancel</button>
                <button type="submit" disabled={formSaving} className="flex-1 py-2.5 bg-primary-600 text-white rounded-xl text-sm font-semibold hover:bg-primary-700 disabled:opacity-50">{formSaving ? 'Adding…' : 'Add Student'}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Edit Student Modal */}
      {showEditStudent && selectedStudent && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full mx-4 p-6">
            <div className="flex items-center justify-between mb-5">
              <h2 className="text-lg font-bold">Edit Student</h2>
              <button onClick={() => setShowEditStudent(false)} className="text-gray-400 hover:text-gray-600"><X className="w-5 h-5" /></button>
            </div>
            <div className="bg-gray-50 rounded-xl px-4 py-3 mb-5 text-sm text-gray-500 font-mono">{selectedStudent.student_id}</div>
            {editError && <div className="bg-danger-50 text-danger-700 text-sm rounded-lg px-4 py-2 mb-4">{editError}</div>}
            <form onSubmit={handleEditStudent} className="space-y-4">
              <div>
                <label className="text-sm font-medium text-gray-700 mb-1 block">Full Name <span className="text-danger-500">*</span></label>
                <input type="text" value={editData.name} onChange={(e) => setEditData({ ...editData, name: e.target.value })} className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400" required autoFocus />
              </div>
              <div>
                <label className="text-sm font-medium text-gray-700 mb-1 block">Class <span className="text-danger-500">*</span></label>
                <select value={editData.studentClass} onChange={(e) => setEditData({ ...editData, studentClass: e.target.value })} className="w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400" required>
                  <option value="">Select Class</option>
                  {classes.map((c) => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div>
                <label className="text-sm font-medium text-gray-700 mb-1 block">Balance Due (₦)</label>
                <p className="text-xs text-gray-400 mb-1">Direct override of the outstanding balance amount.</p>
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 font-bold text-gray-500">₦</span>
                  <input type="number" min="0" step="0.01" value={editData.feesOwed} onChange={(e) => setEditData({ ...editData, feesOwed: e.target.value })} className="w-full pl-8 pr-3 py-3 border border-gray-200 rounded-xl text-xl font-bold focus:outline-none focus:ring-2 focus:ring-primary-400" />
                </div>
              </div>
              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setShowEditStudent(false)} className="flex-1 py-2.5 bg-gray-100 rounded-xl text-sm font-medium hover:bg-gray-200">Cancel</button>
                <button type="submit" disabled={editSaving} className="flex-1 py-2.5 bg-primary-600 text-white rounded-xl text-sm font-semibold hover:bg-primary-700 disabled:opacity-50">{editSaving ? 'Saving…' : 'Save Changes'}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Delete Confirm */}
      {showDeleteConfirm && selectedStudent && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full mx-4 p-6 text-center">
            <div className="w-14 h-14 bg-danger-100 rounded-full flex items-center justify-center mx-auto mb-4"><Trash2 className="w-7 h-7 text-danger-600" /></div>
            <h2 className="text-lg font-bold mb-2">Delete Student?</h2>
            <p className="text-sm text-gray-500 mb-5">Delete <strong>{selectedStudent.name}</strong> ({selectedStudent.student_id})? This cannot be undone.</p>
            <div className="flex gap-3">
              <button onClick={() => { setShowDeleteConfirm(false); setSelectedStudent(null); }} className="flex-1 py-2.5 bg-gray-100 rounded-xl text-sm font-medium hover:bg-gray-200">Cancel</button>
              <button onClick={handleDelete} className="flex-1 py-2.5 bg-danger-600 text-white rounded-xl text-sm font-semibold hover:bg-danger-700">Delete</button>
            </div>
          </div>
        </div>
      )}

      {/* History Modal */}
      {showHistory && selectedStudent && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full mx-4 p-6 max-h-[90vh] overflow-auto">
            <div className="flex justify-between items-center mb-4">
              <div>
                <h2 className="text-xl font-bold">Transaction History</h2>
                <p className="text-gray-500">{selectedStudent.name} - {selectedStudent.student_id}</p>
              </div>
              <button onClick={() => setShowHistory(false)} className="text-gray-400 hover:text-gray-600"><X className="w-5 h-5" /></button>
            </div>
            {history.length === 0 ? (
              <div className="text-center py-8 text-gray-400">No transactions found</div>
            ) : (
              <table className="w-full text-sm">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="text-left px-3 py-2">Date</th>
                    <th className="text-left px-3 py-2">Type</th>
                    <th className="text-left px-3 py-2">Items</th>
                    <th className="text-left px-3 py-2">Payment</th>
                    <th className="text-right px-3 py-2">Amount</th>
                  </tr>
                </thead>
                <tbody>
                  {history.map((h) => (
                    <tr key={h.transaction_id} className="border-t">
                      <td className="px-3 py-2">{new Date(h.timestamp).toLocaleDateString()}</td>
                      <td className="px-3 py-2"><span className={`px-2 py-1 rounded text-xs ${h.type === 'STORE_PURCHASE' ? 'bg-primary-100 text-primary-700' : h.type === 'REGISTRATION_PAYMENT' ? 'bg-warning-100 text-warning-700' : 'bg-success-100 text-success-700'}`}>{h.type === 'STORE_PURCHASE' ? 'Store' : h.type === 'REGISTRATION_PAYMENT' ? 'Reg.' : 'Fees'}</span></td>
                      <td className="px-3 py-2 max-w-xs truncate">{h.items_summary || '-'}</td>
                      <td className="px-3 py-2">{h.payment_mode}</td>
                      <td className="px-3 py-2 text-right font-semibold">{fmt(Number(h.amount_paid))}</td>
                    </tr>
                  ))}
                </tbody>
                <tfoot className="font-bold border-t-2">
                  <tr>
                    <td colSpan={4} className="px-3 py-2">Total:</td>
                    <td className="px-3 py-2 text-right">{fmt(history.reduce((s, h) => s + Number(h.amount_paid), 0))}</td>
                  </tr>
                </tfoot>
              </table>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentManagement;

