    42→  async open(userId: number, openingCash: number) {
    43→    const { data: existing } = await supabase.from('shifts').select('id').eq('status', 'open').maybeSingle();
    44→    if (existing) throw new Error('A shift is already open. Close it first.');
    45→    const { data, error } = await supabase.from('shifts').insert({ user_id: userId, opening_cash: openingCash, status: 'open' }).select().single();
    46→    if (error) throw error;
    47→    return { success: true, shiftId: data.id };
    48→  },
    49→  async close(shiftId: number, closingCash: number) {
    50→    const { data: shift } = await supabase.from('shifts').select('*').eq('id', shiftId).single();
    51→    if (!shift) throw new Error('Shift not found');
    52→    const { data: cashSales } = await supabase.from('transactions').select('amount_paid').eq('shift_id', shiftId).eq('payment_mode', 'Cash');
    53→    const totalCashSales = (cashSales || []).reduce((s: number, t: any) => s + Number(t.amount_paid), 0);
    54→    const expectedCash = Number(shift.opening_cash) + totalCashSales;
    55→    const difference = closingCash - expectedCash;
    56→    const { error } = await supabase.from('shifts').update({ closing_cash: closingCash, expected_closing_cash: expectedCash, cash_difference: difference, closed_at: new Date().toISOString(), status: 'closed' }).eq('id', shiftId);
