   285→      if (feeCategory === 'standard') query = query.eq('admission_type', 'Returning');
   286→    }
   287→
   288→    const { data: students } = await query;
   289→    if (!students || students.length === 0) return { success: true, count: 0 };
   290→
   291→    const rows = students.map((s: any) => ({ student_id: s.student_id, fee_type_id: feeTypeId, amount_due: amount, amount_paid: 0 }));
   292→    const { error } = await supabase.from('student_fees').upsert(rows, { onConflict: 'student_id,fee_type_id', ignoreDuplicates: true });
   293→    if (error) return { success: false, error: error.message };
   294→
   295→    // Update each student's current_fees_owed
   296→    for (const s of students) {
   297→      const newOwed = Number(s.current_fees_owed || 0) + amount;
   298→      await supabase.from('students').update({ current_fees_owed: newOwed, updated_at: new Date().toISOString() }).eq('student_id', s.student_id);
   299→    }

