import React, { useState, useEffect } from 'react';
import { Plus, Pencil, X, Tag, AlertCircle } from 'lucide-react';
import { inventoryAPI, categoryAPI } from '../../lib/api';

const fmt = (n: number) => `₦${(n || 0).toLocaleString('en-NG', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

interface Item { item_id: number; item_name: string; cost_price: number; selling_price: number; stock_quantity: number; barcode: string | null; category_id: number | null; category_name: string | null; category_color: string | null; }
interface Category { id: number; name: string; color: string; }
type FormData = { itemName: string; costPrice: string; sellingPrice: string; stockQuantity: string; barcode: string; categoryId: string; };
const emptyForm: FormData = { itemName: '', costPrice: '', sellingPrice: '', stockQuantity: '', barcode: '', categoryId: '' };

const inputCls = 'w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400';
const labelCls = 'text-sm font-medium text-gray-700 mb-1 block';

const InventoryManagement: React.FC = () => {
  const [inventory, setInventory] = useState<Item[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [lowStock, setLowStock] = useState(false);
  const [catFilter, setCatFilter] = useState<string>('all');

  const [showAdd, setShowAdd] = useState(false);
  const [showEdit, setShowEdit] = useState(false);
  const [showAdjust, setShowAdjust] = useState(false);
  const [showCatMgr, setShowCatMgr] = useState(false);
  const [selected, setSelected] = useState<Item | null>(null);

  // Separate form states so edits are independent
  const [addForm, setAddForm] = useState<FormData>(emptyForm);
  const [editForm, setEditForm] = useState<FormData>(emptyForm);
  const [addError, setAddError] = useState('');

  // Adjust stock state — absolute new quantity
  const [adjNewQty, setAdjNewQty] = useState('');
  const [adjError, setAdjError] = useState('');

  // Category manager state
  const [catForm, setCatForm] = useState({ name: '', color: '#3b82f6' });
  const [editCat, setEditCat] = useState<Category | null>(null);
  const [errorMsg, setErrorMsg] = useState('');

  const reload = () => {
    setLoading(true);
    Promise.all([
      inventoryAPI.getAll({ search, lowStock, categoryId: catFilter !== 'all' ? Number(catFilter) : null }),
      categoryAPI.getAll(),
    ]).then(([inv, cats]) => { setInventory(inv); setCategories(cats); }).catch(console.error).finally(() => setLoading(false));
  };

  useEffect(() => { reload(); }, [search, lowStock, catFilter]);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    setAddError('');
    const result = await inventoryAPI.create({
      itemName: addForm.itemName, costPrice: parseFloat(addForm.costPrice), sellingPrice: parseFloat(addForm.sellingPrice),
      stockQuantity: parseInt(addForm.stockQuantity) || 0, barcode: addForm.barcode || undefined,
      categoryId: addForm.categoryId ? Number(addForm.categoryId) : null,
    });
    if (result.success) { setShowAdd(false); setAddForm(emptyForm); reload(); }
    else setAddError(result.error || 'Failed to create item');
  };

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selected) return;
    await inventoryAPI.update(selected.item_id, {
      itemName: editForm.itemName, costPrice: parseFloat(editForm.costPrice), sellingPrice: parseFloat(editForm.sellingPrice),
      barcode: editForm.barcode || undefined, categoryId: editForm.categoryId ? Number(editForm.categoryId) : null,
    });
    setShowEdit(false);
    reload();
  };

  const handleAdjust = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selected) return;
    const qty = parseInt(adjNewQty);
    if (isNaN(qty) || qty < 0) { setAdjError('Enter a valid stock total (≥ 0)'); return; }
    setAdjError('');
    await inventoryAPI.setStock(selected.item_id, qty);
    setShowAdjust(false);
    setAdjNewQty('');
    reload();
  };

  const openEdit = (item: Item) => {
    setSelected(item);
    setEditForm({ itemName: item.item_name, costPrice: String(item.cost_price), sellingPrice: String(item.selling_price), stockQuantity: String(item.stock_quantity), barcode: item.barcode || '', categoryId: item.category_id ? String(item.category_id) : '' });
    setShowEdit(true);
  };

  const saveCat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editCat) {
      await categoryAPI.update(editCat.id, catForm.name, catForm.color);
    } else {
      const r = await categoryAPI.create(catForm.name, catForm.color);
      if (!r.success) { setErrorMsg(r.error || 'Failed to create category'); return; }
    }
    setCatForm({ name: '', color: '#3b82f6' });
    setEditCat(null);
    categoryAPI.getAll().then(setCategories);
  };

  const totalValue = inventory.reduce((s, i) => s + i.stock_quantity * i.selling_price, 0);

  return (
    <div>
      {errorMsg && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full mx-4 p-6 text-center">
            <div className="w-14 h-14 bg-danger-100 rounded-full flex items-center justify-center mx-auto mb-4"><AlertCircle className="w-7 h-7 text-danger-600" /></div>
            <h2 className="text-lg font-bold mb-2">Error</h2>
            <p className="text-gray-600 text-sm mb-5">{errorMsg}</p>
            <button onClick={() => setErrorMsg('')} className="w-full py-2.5 bg-gray-100 rounded-xl text-gray-700 hover:bg-gray-200 font-medium">OK</button>
          </div>
        </div>
      )}

      <div className="flex items-center justify-between mb-5">
        <div>
          <h1 className="text-2xl font-extrabold text-gray-900">Inventory</h1>
          <p className="text-sm text-gray-400 mt-0.5">{inventory.length} items · {fmt(totalValue)} total retail value</p>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => setShowCatMgr(true)} className="flex items-center gap-2 px-3 py-2 bg-gray-100 text-gray-700 rounded-lg text-sm font-medium hover:bg-gray-200">
            <Tag className="w-4 h-4" /> Categories
          </button>
          <button onClick={() => { setAddForm(emptyForm); setAddError(''); setShowAdd(true); }} className="flex items-center gap-2 px-4 py-2 bg-primary-600 text-white rounded-lg text-sm font-semibold hover:bg-primary-700">
            <Plus className="w-4 h-4" /> Add Item
          </button>
        </div>
      </div>

      <div className="grid grid-cols-4 gap-4 mb-5">
        {[
          { label: 'SKUs', value: inventory.length },
          { label: 'Total Units', value: inventory.reduce((s, i) => s + i.stock_quantity, 0).toLocaleString() },
          { label: 'Retail Value', value: fmt(totalValue) },
          { label: 'Low Stock (≤10)', value: inventory.filter((i) => i.stock_quantity <= 10).length, danger: true },
        ].map((s, idx) => (
          <div key={idx} className="bg-white rounded-xl border border-gray-100 shadow-sm p-5">
            <div className="text-xs text-gray-400 font-semibold uppercase mb-1">{s.label}</div>
            <div className={`text-2xl font-extrabold ${s.danger && Number(s.value) > 0 ? 'text-danger-600' : 'text-gray-900'}`}>{s.value}</div>
          </div>
        ))}
      </div>

      <div className="bg-white rounded-xl border border-gray-100 shadow-sm p-4 mb-5 flex items-center gap-3 flex-wrap">
        <input type="text" value={search} onChange={(e) => setSearch(e.target.value)} className="flex-1 min-w-48 px-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400" placeholder="Search items or barcode…" />
        <select value={catFilter} onChange={(e) => setCatFilter(e.target.value)} className="border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary-400">
          <option value="all">All Categories</option>
          {categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
        </select>
        <label className="flex items-center gap-2 cursor-pointer text-sm">
          <input type="checkbox" checked={lowStock} onChange={(e) => setLowStock(e.target.checked)} className="rounded" />
          Low stock only
        </label>
      </div>

      <div className="bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden">
        <table className="w-full text-sm">
          <thead className="bg-gray-50 border-b">
            <tr>
              {['Item Name', 'Category', 'Barcode', 'Cost', 'Selling Price', 'Stock', 'Profit/Unit', 'Actions'].map((h) => (
                <th key={h} className={`px-4 py-3 text-xs font-semibold text-gray-400 uppercase tracking-wider ${h === 'Actions' ? 'text-center' : h === 'Cost' || h === 'Selling Price' || h === 'Stock' || h === 'Profit/Unit' ? 'text-right' : 'text-left'}`}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr><td colSpan={8} className="text-center py-12 text-gray-400">Loading…</td></tr>
            ) : inventory.length === 0 ? (
              <tr><td colSpan={8} className="text-center py-12 text-gray-400">No items found</td></tr>
            ) : inventory.map((item) => (
              <tr key={item.item_id} className={`border-t hover:bg-gray-50 ${item.stock_quantity <= 10 && item.stock_quantity > 0 ? 'bg-warning-50' : item.stock_quantity <= 0 ? 'bg-danger-50' : ''}`}>
                <td className="px-4 py-3 font-medium text-gray-900">{item.item_name}</td>
                <td className="px-4 py-3">
                  {item.category_name ? (
                    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-semibold text-white" style={{ background: item.category_color || '#6b7280' }}>{item.category_name}</span>
                  ) : <span className="text-gray-300 text-xs">—</span>}
                </td>
                <td className="px-4 py-3 font-mono text-xs text-gray-400">{item.barcode || '—'}</td>
                <td className="px-4 py-3 text-right text-gray-500">{fmt(item.cost_price)}</td>
                <td className="px-4 py-3 text-right font-semibold text-primary-600">{fmt(item.selling_price)}</td>
                <td className={`px-4 py-3 text-right font-bold ${item.stock_quantity <= 0 ? 'text-danger-600' : item.stock_quantity <= 10 ? 'text-warning-600' : 'text-gray-900'}`}>{item.stock_quantity}</td>
                <td className="px-4 py-3 text-right text-success-600 font-medium">{fmt(item.selling_price - item.cost_price)}</td>
                <td className="px-4 py-3 text-center">
                  <button onClick={() => openEdit(item)} className="p-1.5 text-gray-400 hover:text-primary-600 hover:bg-primary-50 rounded-lg mr-1 transition-colors"><Pencil className="w-4 h-4" /></button>
                  <button onClick={() => { setSelected(item); setAdjNewQty(String(item.stock_quantity)); setAdjError(''); setShowAdjust(true); }} className="px-2 py-1 text-xs bg-warning-100 text-warning-700 rounded-lg hover:bg-warning-200 font-medium">Stock</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Add Item Modal — inline form (no inner component = no focus loss) */}
      {showAdd && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full mx-4 p-6 max-h-[90vh] overflow-auto">
            <div className="flex items-center justify-between mb-5"><h2 className="text-lg font-bold">Add New Item</h2><button onClick={() => setShowAdd(false)}><X className="w-5 h-5 text-gray-400" /></button></div>
            {addError && <div className="bg-danger-50 text-danger-700 text-sm rounded-lg px-4 py-2 mb-4">{addError}</div>}
            <form onSubmit={handleCreate} className="space-y-4">
              <div>
                <label className={labelCls}>Item Name *</label>
                <input type="text" className={inputCls} required autoFocus value={addForm.itemName} onChange={(e) => setAddForm((p) => ({ ...p, itemName: e.target.value }))} />
              </div>
              <div>
                <label className={labelCls}>Category</label>
                <select className={inputCls} value={addForm.categoryId} onChange={(e) => setAddForm((p) => ({ ...p, categoryId: e.target.value }))}>
                  <option value="">No Category</option>
                  {categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
              <div>
                <label className={labelCls}>Barcode (optional)</label>
                <input type="text" className={inputCls} value={addForm.barcode} onChange={(e) => setAddForm((p) => ({ ...p, barcode: e.target.value }))} />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className={labelCls}>Cost Price *</label>
                  <input type="number" min="0" step="0.01" className={inputCls} required value={addForm.costPrice} onChange={(e) => setAddForm((p) => ({ ...p, costPrice: e.target.value }))} />
                </div>
                <div>
                  <label className={labelCls}>Selling Price *</label>
                  <input type="number" min="0" step="0.01" className={inputCls} required value={addForm.sellingPrice} onChange={(e) => setAddForm((p) => ({ ...p, sellingPrice: e.target.value }))} />
                </div>
              </div>
              <div>
                <label className={labelCls}>Initial Stock</label>
                <input type="number" min="0" className={inputCls} value={addForm.stockQuantity} onChange={(e) => setAddForm((p) => ({ ...p, stockQuantity: e.target.value }))} />
              </div>
              {addForm.costPrice && addForm.sellingPrice && (
                <div className="bg-gray-50 rounded-lg px-3 py-2 text-sm">
                  Profit per unit: <strong className="text-success-600">{fmt(parseFloat(addForm.sellingPrice || '0') - parseFloat(addForm.costPrice || '0'))}</strong>
                </div>
              )}
              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setShowAdd(false)} className="flex-1 py-2.5 bg-gray-100 rounded-xl text-sm font-medium hover:bg-gray-200">Cancel</button>
                <button type="submit" className="flex-1 py-2.5 bg-primary-600 text-white rounded-xl text-sm font-semibold hover:bg-primary-700">Add Item</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Edit Item Modal — NO Initial Stock field */}
      {showEdit && selected && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full mx-4 p-6 max-h-[90vh] overflow-auto">
            <div className="flex items-center justify-between mb-5"><h2 className="text-lg font-bold">Edit: {selected.item_name}</h2><button onClick={() => setShowEdit(false)}><X className="w-5 h-5 text-gray-400" /></button></div>
            <form onSubmit={handleUpdate} className="space-y-4">
              <div>
                <label className={labelCls}>Item Name *</label>
                <input type="text" className={inputCls} required autoFocus value={editForm.itemName} onChange={(e) => setEditForm((p) => ({ ...p, itemName: e.target.value }))} />
              </div>
              <div>
                <label className={labelCls}>Category</label>
                <select className={inputCls} value={editForm.categoryId} onChange={(e) => setEditForm((p) => ({ ...p, categoryId: e.target.value }))}>
                  <option value="">No Category</option>
                  {categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
              <div>
                <label className={labelCls}>Barcode (optional)</label>
                <input type="text" className={inputCls} value={editForm.barcode} onChange={(e) => setEditForm((p) => ({ ...p, barcode: e.target.value }))} />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className={labelCls}>Cost Price *</label>
                  <input type="number" min="0" step="0.01" className={inputCls} required value={editForm.costPrice} onChange={(e) => setEditForm((p) => ({ ...p, costPrice: e.target.value }))} />
                </div>
                <div>
                  <label className={labelCls}>Selling Price *</label>
                  <input type="number" min="0" step="0.01" className={inputCls} required value={editForm.sellingPrice} onChange={(e) => setEditForm((p) => ({ ...p, sellingPrice: e.target.value }))} />
                </div>
              </div>
              {editForm.costPrice && editForm.sellingPrice && (
                <div className="bg-gray-50 rounded-lg px-3 py-2 text-sm">
                  Profit per unit: <strong className="text-success-600">{fmt(parseFloat(editForm.sellingPrice || '0') - parseFloat(editForm.costPrice || '0'))}</strong>
                </div>
              )}
              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setShowEdit(false)} className="flex-1 py-2.5 bg-gray-100 rounded-xl text-sm font-medium hover:bg-gray-200">Cancel</button>
                <button type="submit" className="flex-1 py-2.5 bg-primary-600 text-white rounded-xl text-sm font-semibold hover:bg-primary-700">Update Item</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Adjust Stock Modal — absolute new total */}
      {showAdjust && selected && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full mx-4 p-6">
            <div className="flex items-center justify-between mb-4"><h2 className="text-lg font-bold">Set Stock</h2><button onClick={() => setShowAdjust(false)}><X className="w-5 h-5 text-gray-400" /></button></div>
            <div className="bg-gray-50 rounded-xl p-4 text-center mb-4">
              <div className="font-bold text-gray-900">{selected.item_name}</div>
              <div className="text-4xl font-extrabold mt-1 text-gray-800">{selected.stock_quantity}</div>
              <div className="text-xs text-gray-400">current units</div>
            </div>
            {adjError && <div className="bg-danger-50 text-danger-700 text-sm rounded-lg px-4 py-2 mb-3">{adjError}</div>}
            <form onSubmit={handleAdjust} className="space-y-3">
              <div>
                <label className={labelCls}>New Stock Total</label>
                <input
                  type="number"
                  min="0"
                  value={adjNewQty}
                  onChange={(e) => { setAdjNewQty(e.target.value); setAdjError(''); }}
                  className="w-full px-3 py-3 border-2 border-gray-200 rounded-xl text-2xl font-bold text-center focus:outline-none focus:border-primary-400"
                  autoFocus
                  required
                />
                {adjNewQty !== '' && !isNaN(parseInt(adjNewQty)) && (
                  <div className={`mt-1 text-sm text-center ${parseInt(adjNewQty) !== selected.stock_quantity ? 'text-warning-700 font-semibold' : 'text-gray-400'}`}>
                    Change: {parseInt(adjNewQty) - selected.stock_quantity >= 0 ? '+' : ''}{parseInt(adjNewQty) - selected.stock_quantity} units
                  </div>
                )}
              </div>
              <div className="flex gap-3 pt-1">
                <button type="button" onClick={() => setShowAdjust(false)} className="flex-1 py-2.5 bg-gray-100 rounded-xl text-sm font-medium hover:bg-gray-200">Cancel</button>
                <button type="submit" className="flex-1 py-2.5 bg-warning-500 text-white rounded-xl text-sm font-semibold hover:bg-warning-600">Set Stock</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Category Manager Modal */}
      {showCatMgr && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full mx-4 p-6">
            <div className="flex items-center justify-between mb-4"><h2 className="text-lg font-bold">Manage Categories</h2><button onClick={() => setShowCatMgr(false)}><X className="w-5 h-5 text-gray-400" /></button></div>
            <form onSubmit={saveCat} className="flex gap-2 mb-4">
              <input type="text" value={catForm.name} onChange={(e) => setCatForm((p) => ({ ...p, name: e.target.value }))} placeholder="Category name" className="flex-1 px-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400" required />
              <input type="color" value={catForm.color} onChange={(e) => setCatForm((p) => ({ ...p, color: e.target.value }))} className="w-10 h-10 rounded-lg border border-gray-200 cursor-pointer p-0.5" title="Category color" />
              <button type="submit" className="px-3 py-2 bg-primary-600 text-white rounded-lg text-sm font-semibold hover:bg-primary-700">{editCat ? 'Save' : 'Add'}</button>
              {editCat && <button type="button" onClick={() => { setEditCat(null); setCatForm({ name: '', color: '#3b82f6' }); }} className="px-3 py-2 bg-gray-200 rounded-lg text-sm hover:bg-gray-300">Cancel</button>}
            </form>
            <div className="space-y-2">
              {categories.map((c) => (
                <div key={c.id} className="flex items-center gap-2 p-2 bg-gray-50 rounded-lg">
                  <div className="w-4 h-4 rounded-full shrink-0" style={{ background: c.color }} />
                  <span className="flex-1 text-sm font-medium">{c.name}</span>
                  <button onClick={() => { setEditCat(c); setCatForm({ name: c.name, color: c.color }); }} className="p-1 text-gray-400 hover:text-primary-600"><Pencil className="w-3.5 h-3.5" /></button>
                  <button onClick={async () => { await categoryAPI.delete(c.id); categoryAPI.getAll().then(setCategories); }} className="p-1 text-gray-400 hover:text-danger-600"><X className="w-3.5 h-3.5" /></button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default InventoryManagement;

import React, { useState, useEffect } from 'react';
import { ChevronLeft, ChevronRight, Trash2, Pencil, X, UserPlus, AlertCircle, ToggleLeft, ToggleRight } from 'lucide-react';
import { studentAPI, feeTypeAPI, settingsAPI } from '../../lib/api';

const fmt = (n: number) => `₦${(n || 0).toLocaleString('en-NG', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

interface Student { student_id: string; name: string; student_class: string; current_fees_owed: number; admission_type?: 'Returning' | 'New'; student_status?: 'Day' | 'Boarding'; }
interface FeeType { id: number; name: string; amount: number; fee_category: string; class_filter: string | null; academic_session: string; }

const DEFAULT_CLASSES = ['JSS1A', 'JSS1B', 'JSS2A', 'JSS2B', 'JSS3A', 'JSS3B', 'SS1A', 'SS1B', 'SS2A', 'SS2B', 'SS3A', 'SS3B'];
const inputCls = 'w-full px-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400';

const StudentManagement: React.FC = () => {
  const [students, setStudents] = useState<Student[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const pageSize = 15;
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedClass, setSelectedClass] = useState('all');
  const [statusFilter, setStatusFilter] = useState<'all' | 'Day' | 'Boarding'>('all');

  const [classes, setClasses] = useState<string[]>(DEFAULT_CLASSES);
  const [feeTypes, setFeeTypes] = useState<FeeType[]>([]);

  const [showModal, setShowModal] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [showEditStudent, setShowEditStudent] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [history, setHistory] = useState<any[]>([]);

  const [formData, setFormData] = useState({
    studentId: '', name: '', studentClass: '', selectedFeeIds: [] as number[],
    admissionType: 'Returning' as 'Returning' | 'New', studentStatus: 'Day' as 'Day' | 'Boarding',
  });
  const [formError, setFormError] = useState('');
  const [formSaving, setFormSaving] = useState(false);

  const [editData, setEditData] = useState({
    name: '', studentClass: '', studentStatus: 'Day' as 'Day' | 'Boarding',
    selectedFeeIds: [] as number[],
    manualAdjOn: false, manualAdjAmount: '', manualAdjReason: '',
  });
  const [editSaving, setEditSaving] = useState(false);
  const [editError, setEditError] = useState('');

  const load = () => {
    setLoading(true);
    studentAPI.getAll({ search, class: selectedClass, page, pageSize })
      .then((d) => { setStudents(d.students); setTotal(d.total); })
      .catch(console.error)
      .finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, [search, selectedClass, page]);

  useEffect(() => {
    settingsAPI.get().then((s) => {
      if (s?.class_list) {
        try {
          const parsed = JSON.parse(s.class_list);
          if (Array.isArray(parsed) && parsed.length > 0) setClasses(parsed.sort());
        } catch { /* use default */ }
      }
    }).catch(console.error);
    feeTypeAPI.getAll().then((ft) => setFeeTypes(ft as FeeType[])).catch(console.error);
  }, []);

  const totalPages = Math.ceil(total / pageSize);

  const computeFeesOwed = () => formData.selectedFeeIds.reduce((sum, id) => {
    const ft = feeTypes.find((f) => f.id === id);
    return sum + (ft ? Number(ft.amount) : 0);
  }, 0);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name.trim() || !formData.studentClass) { setFormError('Name and class are required.'); return; }
    setFormSaving(true);
    setFormError('');
    const feesOwed = computeFeesOwed();
    const result = await studentAPI.create({
      studentId: formData.studentId || undefined,
      name: formData.name,
      studentClass: formData.studentClass,
      feesOwed,
      admissionType: formData.admissionType,
      studentStatus: formData.studentStatus,
    });
    if (result.success) {
      for (const feeId of formData.selectedFeeIds) {
        const ft = feeTypes.find((f) => f.id === feeId);
        if (ft) await feeTypeAPI.assignToStudents(feeId, Number(ft.amount), undefined, result.studentId, ft.fee_category as 'standard' | 'registration');
      }
      setShowModal(false);
      setFormData({ studentId: '', name: '', studentClass: '', selectedFeeIds: [], admissionType: 'Returning', studentStatus: 'Day' });
      load();
    } else setFormError(result.error || 'Failed to create student');
    setFormSaving(false);
  };

  const viewHistory = async (s: Student) => {
    setSelectedStudent(s);
    const h = await studentAPI.getHistory(s.student_id);
    setHistory(h);
    setShowHistory(true);
  };

  const openDeleteConfirm = (s: Student) => { setSelectedStudent(s); setShowDeleteConfirm(true); };
  const handleDelete = async () => {
    if (!selectedStudent) return;
    await studentAPI.delete(selectedStudent.student_id);
    setShowDeleteConfirm(false);
    setSelectedStudent(null);
    load();
  };

  const openEditStudent = (s: Student) => {
    setSelectedStudent(s);
    setEditData({
      name: s.name, studentClass: s.student_class,
      studentStatus: (s.student_status as 'Day' | 'Boarding') || 'Day',
      selectedFeeIds: [],
      manualAdjOn: false, manualAdjAmount: '', manualAdjReason: '',
    });
    setEditError('');
    setShowEditStudent(true);
  };

  const handleEditStudent = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedStudent) return;
    if (!editData.name.trim() || !editData.studentClass) { setEditError('Name and class are required.'); return; }
    if (editData.manualAdjOn && !editData.manualAdjReason.trim()) { setEditError('Please provide a reason for the manual adjustment.'); return; }
    if (editData.manualAdjOn && editData.manualAdjAmount === '') { setEditError('Please enter an adjustment amount.'); return; }
    setEditSaving(true);
    setEditError('');
    try {
      await studentAPI.update(selectedStudent.student_id, {
        name: editData.name.trim(),
        studentClass: editData.studentClass,
        studentStatus: editData.studentStatus,
      });
      // Assign selected fee templates
      for (const feeId of editData.selectedFeeIds) {
        const ft = feeTypes.find((f) => f.id === feeId);
        if (ft) await feeTypeAPI.assignToStudents(feeId, Number(ft.amount), undefined, selectedStudent.student_id, ft.fee_category as 'standard' | 'registration');
      }
      // Manual adjustment: apply balance change
      if (editData.manualAdjOn && editData.manualAdjAmount !== '') {
        const adjAmount = parseFloat(editData.manualAdjAmount);
        if (!isNaN(adjAmount)) {
          const newBalance = Math.max(0, selectedStudent.current_fees_owed + adjAmount);
          await studentAPI.updateFees(selectedStudent.student_id, newBalance);
        }
      }
      setShowEditStudent(false);
      setSelectedStudent(null);
      load();
    } catch (e) { setEditError((e as Error).message); }
    setEditSaving(false);
  };

  const toggleFeeSelection = (id: number) => {
    setFormData((prev) => ({
      ...prev,
      selectedFeeIds: prev.selectedFeeIds.includes(id)
        ? prev.selectedFeeIds.filter((x) => x !== id)
        : [...prev.selectedFeeIds, id],
    }));
  };

  const toggleEditFeeSelection = (id: number) => {
    setEditData((prev) => ({
      ...prev,
      selectedFeeIds: prev.selectedFeeIds.includes(id)
        ? prev.selectedFeeIds.filter((x) => x !== id)
        : [...prev.selectedFeeIds, id],
    }));
  };

  const filteredFeeTypes = feeTypes.filter((ft) =>
    !ft.class_filter || !formData.studentClass || ft.class_filter === formData.studentClass
  );

  const editFeeTypes = feeTypes.filter((ft) =>
    !ft.class_filter || !editData.studentClass || ft.class_filter === editData.studentClass
  );

  const filteredStudents = statusFilter === 'all' ? students
    : students.filter((s) => (s.student_status || 'Day') === statusFilter);

  const totalFees = students.reduce((sum, s) => sum + s.current_fees_owed, 0);

  const saveDisabled = editSaving || (editData.manualAdjOn && !editData.manualAdjReason.trim());

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl font-bold">Student Management</h1>
          <p className="text-gray-500">{total} students · ₦{totalFees.toLocaleString('en-NG', { minimumFractionDigits: 2 })} shown outstanding</p>
        </div>
        <button
          onClick={() => { setFormData({ studentId: '', name: '', studentClass: '', selectedFeeIds: [], admissionType: 'Returning', studentStatus: 'Day' }); setFormError(''); setShowModal(true); }}
          className="flex items-center gap-2 px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 font-semibold"
        >
          <UserPlus className="w-4 h-4" /> Add Student
        </button>
      </div>

      <div className="bg-white rounded-lg shadow-sm p-4 mb-6">
        <div className="flex gap-4 flex-wrap">
          <input type="text" value={search} onChange={(e) => { setSearch(e.target.value); setPage(1); }} className="flex-1 min-w-40 px-3 py-2 border rounded-md text-sm" placeholder="Search by name or ID..." />
          <select value={selectedClass} onChange={(e) => { setSelectedClass(e.target.value); setPage(1); }} className="px-3 py-2 border rounded-md text-sm">
            <option value="all">All Classes</option>
            {classes.map((c) => <option key={c} value={c}>{c}</option>)}
          </select>
          <div className="flex gap-1">
            {(['all', 'Day', 'Boarding'] as const).map((s) => (
              <button key={s} onClick={() => setStatusFilter(s)} className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${statusFilter === s ? 'bg-primary-600 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}>
                {s === 'all' ? 'All' : s}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-sm overflow-hidden">
        <table className="w-full text-sm">
          <thead className="bg-gray-50">
            <tr>
              <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase">Student ID</th>
              <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase">Name</th>
              <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase">Class</th>
              <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase">Type / Status</th>
              <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase">Fees Owed</th>
              <th className="text-center px-4 py-3 text-xs font-medium text-gray-500 uppercase">Actions</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr><td colSpan={6} className="text-center py-12 text-gray-400">Loading...</td></tr>
            ) : filteredStudents.length === 0 ? (
              <tr><td colSpan={6} className="text-center py-12 text-gray-400">No students found</td></tr>
            ) : filteredStudents.map((s) => (
              <tr key={s.student_id} className="border-t hover:bg-gray-50">
                <td className="px-4 py-3 font-mono text-sm">{s.student_id}</td>
                <td className="px-4 py-3 font-medium">{s.name}</td>
                <td className="px-4 py-3"><span className="px-2 py-1 bg-primary-100 text-primary-800 rounded text-xs">{s.student_class}</span></td>
                <td className="px-4 py-3">
                  <div className="flex items-center gap-1 flex-wrap">
                    <span className={`px-2 py-0.5 rounded text-xs ${(s.admission_type || 'Returning') === 'Returning' ? 'bg-gray-100 text-gray-700' : 'bg-warning-100 text-warning-700'}`}>{s.admission_type || 'Returning'}</span>
                    <span className={`px-2 py-0.5 rounded text-xs ${(s.student_status || 'Day') === 'Boarding' ? 'bg-indigo-100 text-indigo-700' : 'bg-gray-100 text-gray-600'}`}>{s.student_status || 'Day'}</span>
                  </div>
                </td>
                <td className={`px-4 py-3 text-right font-semibold ${s.current_fees_owed > 0 ? 'text-danger-600' : 'text-success-600'}`}>{fmt(s.current_fees_owed)}</td>
                <td className="px-4 py-3 text-center">
                  <button onClick={() => viewHistory(s)} className="px-2 py-1 text-sm bg-gray-100 rounded mr-1 hover:bg-gray-200">History</button>
                  <button onClick={() => openEditStudent(s)} className="px-2 py-1 text-sm bg-primary-100 text-primary-700 rounded mr-1 hover:bg-primary-200 inline-flex items-center gap-1"><Pencil className="w-3 h-3" /> Edit</button>
                  <button onClick={() => openDeleteConfirm(s)} className="px-2 py-1 text-sm bg-danger-100 text-danger-700 rounded hover:bg-danger-200">Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-3 mt-4">
          <button onClick={() => setPage((p) => Math.max(1, p - 1))} disabled={page <= 1} className="p-2 rounded-lg bg-white border hover:bg-gray-50 disabled:opacity-30"><ChevronLeft className="w-4 h-4" /></button>
          <span className="text-sm text-gray-500 font-medium">Page {page} of {totalPages} ({total} students)</span>
          <button onClick={() => setPage((p) => Math.min(totalPages, p + 1))} disabled={page >= totalPages} className="p-2 rounded-lg bg-white border hover:bg-gray-50 disabled:opacity-30"><ChevronRight className="w-4 h-4" /></button>
        </div>
      )}

      {/* Add Student Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full mx-4 p-6 max-h-[90vh] overflow-auto">
            <div className="flex items-center justify-between mb-5">
              <h2 className="text-lg font-bold">Add New Student</h2>
              <button onClick={() => setShowModal(false)} className="text-gray-400 hover:text-gray-600"><X className="w-5 h-5" /></button>
            </div>
            {formError && <div className="bg-danger-50 text-danger-700 text-sm rounded-lg px-4 py-2 mb-4">{formError}</div>}
            <form onSubmit={handleCreate} className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-1">Student ID <span className="text-gray-400 font-normal">(optional)</span></label>
                <input type="text" value={formData.studentId} onChange={(e) => setFormData({ ...formData, studentId: e.target.value })} className={inputCls} placeholder="Auto-generated as OIS-XXXX if empty" />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Full Name <span className="text-danger-500">*</span></label>
                <input type="text" value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} className={inputCls} required autoFocus />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Class <span className="text-danger-500">*</span></label>
                <select value={formData.studentClass} onChange={(e) => setFormData({ ...formData, studentClass: e.target.value, selectedFeeIds: [] })} className={inputCls} required>
                  <option value="">Select Class</option>
                  {classes.map((c) => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Admission Type</label>
                <div className="grid grid-cols-2 gap-2">
                  <button type="button" onClick={() => setFormData({ ...formData, admissionType: 'Returning' })} className={`py-2.5 rounded-lg text-sm font-semibold border-2 transition-all ${formData.admissionType === 'Returning' ? 'bg-primary-600 border-primary-600 text-white' : 'bg-white border-gray-200 text-gray-600 hover:border-primary-400'}`}>Returning</button>
                  <button type="button" onClick={() => setFormData({ ...formData, admissionType: 'New' })} className={`py-2.5 rounded-lg text-sm font-semibold border-2 transition-all ${formData.admissionType === 'New' ? 'bg-warning-500 border-warning-500 text-white' : 'bg-white border-gray-200 text-gray-600 hover:border-warning-400'}`}>New</button>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Student Status</label>
                <div className="grid grid-cols-2 gap-2">
                  <button type="button" onClick={() => setFormData({ ...formData, studentStatus: 'Day' })} className={`py-2.5 rounded-lg text-sm font-semibold border-2 transition-all ${formData.studentStatus === 'Day' ? 'bg-gray-700 border-gray-700 text-white' : 'bg-white border-gray-200 text-gray-600 hover:border-gray-400'}`}>Day</button>
                  <button type="button" onClick={() => setFormData({ ...formData, studentStatus: 'Boarding' })} className={`py-2.5 rounded-lg text-sm font-semibold border-2 transition-all ${formData.studentStatus === 'Boarding' ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-gray-200 text-gray-600 hover:border-indigo-400'}`}>Boarding</button>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Initial Fees to Apply</label>
                <p className="text-xs text-gray-400 mb-2">Select fee templates to apply to this student.</p>
                {feeTypes.length === 0 ? (
                  <p className="text-xs text-gray-400 italic">No fee types found. Create fee types in Fees Management first.</p>
                ) : filteredFeeTypes.length === 0 ? (
                  <p className="text-xs text-gray-400 italic">No fees available for the selected class.</p>
                ) : (
                  <div className="space-y-2 max-h-40 overflow-auto border border-gray-200 rounded-lg p-2">
                    {filteredFeeTypes.map((ft) => (
                      <label key={ft.id} className={`flex items-center justify-between px-3 py-2 rounded-lg cursor-pointer border transition-all ${formData.selectedFeeIds.includes(ft.id) ? 'border-primary-400 bg-primary-50' : 'border-gray-100 hover:bg-gray-50'}`}>
                        <div className="flex items-center gap-2">
                          <input type="checkbox" checked={formData.selectedFeeIds.includes(ft.id)} onChange={() => toggleFeeSelection(ft.id)} className="rounded" />
                          <div>
                            <div className="text-sm font-medium text-gray-800">{ft.name}</div>
                            {ft.class_filter && <div className="text-xs text-gray-400">{ft.class_filter}</div>}
                          </div>
                        </div>
                        <span className="text-sm font-bold text-gray-700">{fmt(Number(ft.amount))}</span>
                      </label>
                    ))}
                  </div>
                )}
                {formData.selectedFeeIds.length > 0 && (
                  <div className="mt-2 text-sm font-semibold text-primary-700">Total fees to apply: {fmt(computeFeesOwed())}</div>
                )}
              </div>
              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setShowModal(false)} className="flex-1 py-2.5 bg-gray-100 rounded-xl text-sm font-medium hover:bg-gray-200">Cancel</button>
                <button type="submit" disabled={formSaving} className="flex-1 py-2.5 bg-primary-600 text-white rounded-xl text-sm font-semibold hover:bg-primary-700 disabled:opacity-50">{formSaving ? 'Adding…' : 'Add Student'}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Edit Student Modal */}
      {showEditStudent && selectedStudent && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full mx-4 p-6 max-h-[90vh] overflow-auto">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-bold">Edit Student</h2>
              <button onClick={() => setShowEditStudent(false)} className="text-gray-400 hover:text-gray-600"><X className="w-5 h-5" /></button>
            </div>
            <div className="bg-gray-50 rounded-xl px-4 py-3 mb-4 text-sm text-gray-500 font-mono">{selectedStudent.student_id}</div>
            {editError && <div className="bg-danger-50 text-danger-700 text-sm rounded-lg px-4 py-2 mb-4">{editError}</div>}
            <form onSubmit={handleEditStudent} className="space-y-4">
              <div>
                <label className="text-sm font-medium text-gray-700 mb-1 block">Full Name <span className="text-danger-500">*</span></label>
                <input type="text" value={editData.name} onChange={(e) => setEditData({ ...editData, name: e.target.value })} className={inputCls} required autoFocus />
              </div>
              <div>
                <label className="text-sm font-medium text-gray-700 mb-1 block">Class <span className="text-danger-500">*</span></label>
                <select value={editData.studentClass} onChange={(e) => setEditData({ ...editData, studentClass: e.target.value, selectedFeeIds: [] })} className={inputCls} required>
                  <option value="">Select Class</option>
                  {classes.map((c) => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div>
                <label className="text-sm font-medium text-gray-700 mb-1 block">Student Status</label>
                <div className="grid grid-cols-2 gap-2">
                  <button type="button" onClick={() => setEditData({ ...editData, studentStatus: 'Day' })} className={`py-2 rounded-lg text-sm font-semibold border-2 transition-all ${editData.studentStatus === 'Day' ? 'bg-gray-700 border-gray-700 text-white' : 'bg-white border-gray-200 text-gray-600 hover:border-gray-400'}`}>Day</button>
                  <button type="button" onClick={() => setEditData({ ...editData, studentStatus: 'Boarding' })} className={`py-2 rounded-lg text-sm font-semibold border-2 transition-all ${editData.studentStatus === 'Boarding' ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-gray-200 text-gray-600 hover:border-indigo-400'}`}>Boarding</button>
                </div>
              </div>

              {/* Balance Due — read-only */}
              <div>
                <label className="text-sm font-medium text-gray-700 mb-1 block">Balance Due (₦)</label>
                <div className="px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl text-xl font-bold text-gray-800 flex items-center justify-between">
                  <span>{fmt(selectedStudent.current_fees_owed)}</span>
                  <span className="text-xs text-gray-400 font-normal">read-only</span>
                </div>
                <p className="text-xs text-gray-400 mt-1">Use manual adjustment below to change this balance.</p>
              </div>

              {/* Fee Template Checklist */}
              <div>
                <label className="text-sm font-medium text-gray-700 mb-1 block">Apply Additional Fee Templates</label>
                <p className="text-xs text-gray-400 mb-2">Check templates to assign new fees to this student.</p>
                {editFeeTypes.length === 0 ? (
                  <p className="text-xs text-gray-400 italic">No fees available for this class.</p>
                ) : (
                  <div className="space-y-2 max-h-36 overflow-auto border border-gray-200 rounded-lg p-2">
                    {editFeeTypes.map((ft) => (
                      <label key={ft.id} className={`flex items-center justify-between px-3 py-2 rounded-lg cursor-pointer border transition-all ${editData.selectedFeeIds.includes(ft.id) ? 'border-primary-400 bg-primary-50' : 'border-gray-100 hover:bg-gray-50'}`}>
                        <div className="flex items-center gap-2">
                          <input type="checkbox" checked={editData.selectedFeeIds.includes(ft.id)} onChange={() => toggleEditFeeSelection(ft.id)} className="rounded" />
                          <span className="text-sm font-medium text-gray-800">{ft.name}</span>
                        </div>
                        <span className="text-sm font-bold text-gray-700">{fmt(Number(ft.amount))}</span>
                      </label>
                    ))}
                  </div>
                )}
              </div>

              {/* Manual Balance Adjustment */}
              <div className="border border-gray-200 rounded-xl p-4">
                <button
                  type="button"
                  onClick={() => setEditData({ ...editData, manualAdjOn: !editData.manualAdjOn, manualAdjAmount: '', manualAdjReason: '' })}
                  className="flex items-center gap-2 text-sm font-semibold text-gray-700 w-full"
                >
                  {editData.manualAdjOn
                    ? <ToggleRight className="w-5 h-5 text-primary-600" />
                    : <ToggleLeft className="w-5 h-5 text-gray-400" />}
                  Manual Balance Adjustment
                </button>
                {editData.manualAdjOn && (
                  <div className="mt-3 space-y-3">
                    <div>
                      <label className="text-xs font-medium text-gray-600 mb-1 block">Adjustment Amount (₦) — use negative to reduce</label>
                      <input type="number" step="0.01" value={editData.manualAdjAmount} onChange={(e) => setEditData({ ...editData, manualAdjAmount: e.target.value })} placeholder="e.g. -5000 or 2000" className={inputCls} />
                      {editData.manualAdjAmount !== '' && !isNaN(parseFloat(editData.manualAdjAmount)) && (
                        <p className="text-xs text-warning-700 mt-1">
                          New balance: {fmt(Math.max(0, selectedStudent.current_fees_owed + parseFloat(editData.manualAdjAmount)))}
                        </p>
                      )}
                    </div>
                    <div>
                      <label className="text-xs font-medium text-gray-600 mb-1 block">Reason <span className="text-danger-500">*</span></label>
                      <textarea value={editData.manualAdjReason} onChange={(e) => setEditData({ ...editData, manualAdjReason: e.target.value })} placeholder="Required — e.g. Scholarship deduction, Overpayment correction…" className="w-full px-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-400 resize-none" rows={2} required={editData.manualAdjOn} />
                    </div>
                  </div>
                )}
              </div>

              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setShowEditStudent(false)} className="flex-1 py-2.5 bg-gray-100 rounded-xl text-sm font-medium hover:bg-gray-200">Cancel</button>
                <button type="submit" disabled={saveDisabled} className="flex-1 py-2.5 bg-primary-600 text-white rounded-xl text-sm font-semibold hover:bg-primary-700 disabled:opacity-50">
                  {editSaving ? 'Saving…' : 'Save Changes'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Delete Confirm */}
      {showDeleteConfirm && selectedStudent && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full mx-4 p-6 text-center">
            <div className="w-14 h-14 bg-danger-100 rounded-full flex items-center justify-center mx-auto mb-4"><Trash2 className="w-7 h-7 text-danger-600" /></div>
            <h2 className="text-lg font-bold mb-2">Delete Student?</h2>
            <p className="text-sm text-gray-500 mb-5">Delete <strong>{selectedStudent.name}</strong> ({selectedStudent.student_id})? This cannot be undone.</p>
            <div className="flex gap-3">
              <button onClick={() => { setShowDeleteConfirm(false); setSelectedStudent(null); }} className="flex-1 py-2.5 bg-gray-100 rounded-xl text-sm font-medium hover:bg-gray-200">Cancel</button>
              <button onClick={handleDelete} className="flex-1 py-2.5 bg-danger-600 text-white rounded-xl text-sm font-semibold hover:bg-danger-700">Delete</button>
            </div>
          </div>
        </div>
      )}

      {/* History Modal */}
      {showHistory && selectedStudent && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full mx-4 p-6 max-h-[90vh] overflow-auto">
            <div className="flex justify-between items-center mb-4">
              <div>
                <h2 className="text-xl font-bold">Transaction History</h2>
                <p className="text-gray-500">{selectedStudent.name} — {selectedStudent.student_id}</p>
              </div>
              <button onClick={() => setShowHistory(false)} className="text-gray-400 hover:text-gray-600"><X className="w-5 h-5" /></button>
            </div>
            {history.length === 0 ? (
              <div className="text-center py-8 text-gray-400">No transactions found</div>
            ) : (
              <table className="w-full text-sm">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="text-left px-3 py-2">Date</th>
                    <th className="text-left px-3 py-2">Type</th>
                    <th className="text-left px-3 py-2">Items</th>
                    <th className="text-left px-3 py-2">Payment</th>
                    <th className="text-right px-3 py-2">Amount</th>
                  </tr>
                </thead>
                <tbody>
                  {history.map((h) => (
                    <tr key={h.transaction_id} className="border-t">
                      <td className="px-3 py-2">{new Date(h.timestamp).toLocaleDateString()}</td>
                      <td className="px-3 py-2"><span className={`px-2 py-1 rounded text-xs ${h.type === 'STORE_PURCHASE' ? 'bg-primary-100 text-primary-700' : h.type === 'REGISTRATION_PAYMENT' ? 'bg-warning-100 text-warning-700' : 'bg-success-100 text-success-700'}`}>{h.type === 'STORE_PURCHASE' ? 'Store' : h.type === 'REGISTRATION_PAYMENT' ? 'Reg.' : 'Fees'}</span></td>
                      <td className="px-3 py-2 max-w-xs truncate">{h.items_summary || '-'}</td>
                      <td className="px-3 py-2">{h.payment_mode}</td>
                      <td className="px-3 py-2 text-right font-semibold">{fmt(Number(h.amount_paid))}</td>
                    </tr>
                  ))}
                </tbody>
                <tfoot className="font-bold border-t-2">
                  <tr>
                    <td colSpan={4} className="px-3 py-2">Total:</td>
                    <td className="px-3 py-2 text-right">{fmt(history.reduce((s, h) => s + Number(h.amount_paid), 0))}</td>
                  </tr>
                </tfoot>
              </table>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentManagement;

arguments.old_string:
async create(data: { firstName: string; lastName: string; proposedClass?: string; phone?: string; notes?: string }) {
  const { data: applicant, error } = await supabase.from('applicants').insert({ first_name: data.firstName, last_name: data.lastName, proposed_class: data.proposedClass || null, phone: data.phone || null, notes: data.notes || null }).select('id').single();
  if (error) return { success: false, error: error.message };
  return { success: true, id: applicant.id };
},

arguments.new_string:
async create(data: { firstName: string; lastName: string; proposedClass?: string; phone?: string; notes?: string; studentStatus?: string }) {
  const base = { first_name: data.firstName, last_name: data.lastName, proposed_class: data.proposedClass || null, phone: data.phone || null, notes: data.notes || null };
  const withStatus = { ...base, student_status: data.studentStatus || 'Day' };
  let res = await supabase.from('applicants').insert(withStatus).select('id').single();
  if (res.error) res = await supabase.from('applicants').insert(base).select('id').single();
  if (res.error) return { success: false, error: res.error.message };
  return { success: true, id: (res.data as any).id };
