  const pageSize = filters?.pageSize || 15;
  const page = filters?.page || 1;
  const from = (page - 1) * pageSize;
  const to = from + pageSize - 1;

  let query = supabase.from('students').select('*', { count: 'exact' }).order('name').range(from, to);
