    52→      return false;
    53→    } catch (err) {
    54→      console.error('Failed to open shift:', err);
    55→      return false;
    56→    }
    57→  }, [refreshShift]);
    58→
    59→  const closeShift = useCallback(async (closingCash: number, userId: number) => {
    60→    if (!activeShift) return null;
    61→
    62→    try {
    63→      const result = await shiftAPI.close(activeShift.id, closingCash, userId);
