    70→      console.error('Failed to close shift:', err);
    71→      return null;
    72→    }
    73→  }, [activeShift]);
    74→
    75→  return (
    76→    <ShiftContext.Provider value={{ activeShift, loading, openShift, closeShift, refreshShift }}>
    77→      {children}
    78→    </ShiftContext.Provider>
    79→  );
    80→}
