    return (data || []).map((b: any) => ({
      ...b,
      applicable_to: b.applicable_to || 'All Students',
      class_category: b.class_category || null,
      coaching_addon: b.coaching_addon || false,
      items: mapBundleItems(b.bundle_items),
    }));
  },
  async getById(id: number) {
